sp_widget.client_script:
api.controller = function() {

    var c = this;


    function fixRecoveryCharts() {

        if (
            !window.Highcharts ||
            !window.Highcharts.charts
        ) {
            return;
        }


        for (
            var i = 0;
            i < window.Highcharts.charts.length;
            i++
        ) {

            var chart =
                window.Highcharts.charts[i];


            if (
                !chart ||
                !chart.renderTo
            ) {
                continue;
            }


            var card = null;


            if (chart.renderTo.closest) {

                card =
                    chart.renderTo.closest(
                        '.cm-ri-chart-card'
                    );

            }


            /*
             * Ignore every chart outside
             * CampusMatch Recovery Insights
             */
            if (!card) {
                continue;
            }


            /* ==================================================
               REPORTS BY CATEGORY
            ================================================== */

            if (
                card.classList.contains(
                    'cm-ri-chart-wide'
                )
            ) {

                try {

                    chart.update({

                        chart: {
                            height: 220,

                            marginTop: 8,
                            marginRight: 12,
                            marginBottom: 58,
                            marginLeft: 62,

                            spacingTop: 0,
                            spacingRight: 0,
                            spacingBottom: 0,
                            spacingLeft: 0,

                            animation: false
                        },


                        credits: {
                            enabled: false
                        },


                        legend: {

                            enabled: true,

                            layout: 'horizontal',

                            align: 'center',

                            verticalAlign: 'bottom',

                            floating: false,

                            /*
                             * Slightly upward
                             */
                            y: -4,

                            margin: 2,
                            padding: 0,

                            symbolWidth: 10,
                            symbolHeight: 10,

                            itemDistance: 16,

                            itemStyle: {
                                color: '#40585C',
                                fontSize: '11px',
                                fontWeight: '600'
                            }

                        },


                        xAxis: {

                            labels: {

                                rotation: -35,

                                y: 15,

                                style: {
                                    color: '#506267',
                                    fontSize: '10px',
                                    fontWeight: '600'
                                }

                            }

                        },


                        yAxis: {

                            labels: {

                                x: -4,

                                style: {
                                    color: '#506267',
                                    fontSize: '11px',
                                    fontWeight: '600'
                                }

                            },


                            title: {

                                margin: 11,

                                style: {
                                    color: '#254B4B',
                                    fontSize: '11px',
                                    fontWeight: '700'
                                }

                            }

                        }

                    }, false);


                    chart.setSize(
                        null,
                        220,
                        false
                    );


                    chart.redraw(false);

                    chart.reflow();

                }
                catch (e) {}

            }


            /* ==================================================
               DONUT CHARTS
            ================================================== */

            else {

                try {

                    var isMatchQuality =
                        card.querySelector('h4') &&
                        card.querySelector('h4')
                            .textContent
                            .trim()
                            .toLowerCase() ===
                            'match quality';


                    chart.update({

                        chart: {

                            height: 220,

                            spacingTop: 2,
                            spacingRight: 3,
                            spacingBottom: 0,
                            spacingLeft: 3,

                            animation: false

                        },


                        credits: {
                            enabled: false
                        },


                        legend: {

                            enabled: true,

                            layout: 'vertical',

                            align: 'center',

                            verticalAlign: 'bottom',

                            floating: false,

                            y: 0,

                            margin: 0,
                            padding: 0,

                            itemMarginTop: 0,
                            itemMarginBottom: 0,

                            symbolWidth: 10,
                            symbolHeight: 10,

                            /*
                             * Match Quality has 3 entries.
                             * Give it enough legend height so
                             * Highcharts does not create ▲ 1/3 ▼.
                             */
                            maxHeight:
                                isMatchQuality ?
                                64 :
                                48,

                            navigation: {
                                enabled: false
                            },

                            itemStyle: {

                                color: '#40585C',

                                /*
                                 * Slightly smaller ONLY for
                                 * Match Quality because it has
                                 * three longer entries.
                                 */
                                fontSize:
                                    isMatchQuality ?
                                    '10px' :
                                    '11px',

                                fontWeight: '600',

                                textOverflow: 'none'

                            }

                        },


                        plotOptions: {

                            pie: {

                                size:
                                    isMatchQuality ?
                                    108 :
                                    112,

                                center: [
                                    '50%',
                                    '36%'
                                ],

                                dataLabels: {
                                    enabled: false
                                }

                            }

                        }

                    }, false);


                    chart.setSize(
                        null,
                        220,
                        false
                    );


                    chart.redraw(false);

                    chart.reflow();

                }
                catch (e) {}

            }

        }

    }


    /*
     * ServiceNow report widgets render asynchronously.
     */

    setTimeout(
        fixRecoveryCharts,
        700
    );


    setTimeout(
        fixRecoveryCharts,
        1600
    );


    setTimeout(
        fixRecoveryCharts,
        3000
    );


    setTimeout(
        fixRecoveryCharts,
        4500
    );

};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH RECOVERY INSIGHTS
   FINAL ALIGNED VERSION
========================================================== */


/* ==========================================================
   FULL WIDTH SECTION
========================================================== */

.cm-ri {
  position: relative;

  width: 100vw;
  max-width: none;

  margin-left: calc(50% - 50vw);

  padding:
    32px
    20px
    68px;

  background: #F7F8F2;

  color: #102E34;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  box-sizing: border-box;

  overflow: visible;
}


.cm-ri *,
.cm-ri *::before,
.cm-ri *::after {
  box-sizing: border-box;
}


/* ==========================================================
   SAME CONTENT WIDTH AS ADMIN DASHBOARD
========================================================== */

.cm-ri-container {
  width: 100%;

  max-width: 1250px;

  margin:
    0
    auto;

  padding-bottom: 8px;
}


/* ==========================================================
   MAIN HEADER
========================================================== */

.cm-ri-header {
  margin-bottom: 25px;
}


.cm-ri-eyebrow {
  display: inline-block;

  margin-bottom: 6px;

  color: #168C70;

  font-size: 10px;
  font-weight: 900;

  letter-spacing: 2px;

  text-transform: uppercase;
}


.cm-ri-header-row {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 24px;
}


.cm-ri-header h2 {
  margin:
    0
    0
    6px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 30px;
  font-weight: 800;

  line-height: 1.15;
}


.cm-ri-header p {
  margin: 0;

  color: #687A7E;

  font-size: 12px;

  line-height: 1.55;
}


/* ==========================================================
   LIVE DATA BADGE
========================================================== */

.cm-ri-live {
  flex-shrink: 0;

  display: inline-flex;

  align-items: center;

  gap: 7px;

  padding:
    7px
    11px;

  border: 1px solid #D2DED8;

  border-radius: 999px;

  background: #FFFFFF;

  color: #506267;

  font-size: 9px;
  font-weight: 800;
}


.cm-ri-live > span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #249D78;

  box-shadow:
    0 0 0 4px
    rgba(36, 157, 120, 0.11);
}


/* ==========================================================
   SECTION HEADINGS
========================================================== */

.cm-ri-section-head {
  margin-bottom: 13px;

  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 20px;
}


.cm-ri-section-kicker {
  display: block;

  margin-bottom: 3px;

  color: #81908C;

  font-size: 8px;
  font-weight: 900;

  letter-spacing: 1.5px;
}


.cm-ri-section-head h3 {
  margin: 0;

  color: #104E45;

  font-size: 17px;
  font-weight: 800;

  line-height: 1.25;
}


.cm-ri-section-head > p {
  margin: 0;

  color: #81908C;

  font-size: 9px;
}


.cm-ri-analytics-head {
  margin-top: 30px;
}


/* ==========================================================
   KPI GRID
========================================================== */

.cm-ri-kpi-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 13px;
}


/* ==========================================================
   KPI CARD
========================================================== */

.cm-ri-kpi-card {
  min-width: 0;

  min-height: 112px;

  padding:
    14px
    16px
    12px;

  overflow: hidden;

  border:
    1px solid
    #D7E2DD;

  border-radius: 16px;

  background: #FFFFFF;

  box-shadow:
    0 4px 14px
    rgba(16, 78, 69, 0.04);

  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    border-color 0.18s ease;
}


.cm-ri-kpi-card:hover {
  transform:
    translateY(-2px);

  border-color: #BFD5CB;

  box-shadow:
    0 8px 20px
    rgba(16, 78, 69, 0.07);
}


/* ==========================================================
   KPI SUBHEADING
========================================================== */

.cm-ri-kpi-label {
  position: relative;

  min-height: 28px;

  padding-left: 15px;

  display: flex;

  align-items: center;

  color: #365B59;

  font-size: 14px;
  font-weight: 800;

  line-height: 1.25;

  letter-spacing: 0.1px;
}


.cm-ri-kpi-label::before {
  content: "";

  position: absolute;

  left: 0;
  top: 50%;

  width: 4px;
  height: 22px;

  border-radius: 999px;

  background: #249D78;

  transform:
    translateY(-50%);
}


/* ==========================================================
   KPI REPORT VALUE
========================================================== */

.cm-ri-score {
  min-height: 65px;

  display: flex;

  align-items: center;

  justify-content: center;
}


.cm-ri-score > * {
  width: 100%;
}


/* ==========================================================
   ANALYTICS GRID
========================================================== */

.cm-ri-chart-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 14px;

  align-items: stretch;

  padding-bottom: 12px;
}


/* ==========================================================
   ANALYTICS CARD
========================================================== */

.cm-ri-chart-card {
  min-width: 0;

  height: 300px;

  padding:
    14px
    13px
    12px;

  display: flex;

  flex-direction: column;

  overflow: hidden;

  border:
    1px solid
    #D7E2DD;

  border-radius: 17px;

  background: #FFFFFF;

  box-shadow:
    0 4px 14px
    rgba(16, 78, 69, 0.045);

  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}


.cm-ri-chart-card:hover {
  transform:
    translateY(-2px);

  border-color: #C2D8CE;

  box-shadow:
    0 8px 20px
    rgba(16, 78, 69, 0.07);
}


/* ==========================================================
   REPORTS BY CATEGORY
========================================================== */

.cm-ri-chart-wide {
  grid-column: span 2;

  overflow: hidden;
}


/* ==========================================================
   CHART CARD HEADER
========================================================== */

.cm-ri-chart-heading {
  width: 100%;

  height: 38px;

  min-height: 38px;

  margin-bottom: 4px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  flex-shrink: 0;
}


.cm-ri-chart-heading > div {
  min-width: 0;

  display: flex;

  align-items: center;

  gap: 9px;
}


/* ==========================================================
   CHART NUMBER
========================================================== */

.cm-ri-chart-index {
  width: 29px;
  height: 29px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 9px;

  background: #EDF5E9;

  color: #168C70;

  font-size: 10px;
  font-weight: 900;

  line-height: 1;
}


/* ==========================================================
   CHART TITLE
========================================================== */

.cm-ri-chart-heading h4 {
  margin: 0;

  color: #104E45;

  font-size: 13px;
  font-weight: 800;

  line-height: 1.2;

  white-space: nowrap;
}


/* ==========================================================
   CHART TYPE BADGE
========================================================== */

.cm-ri-chart-type {
  min-height: 24px;

  margin: 0;

  padding:
    5px
    10px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  align-self: center;

  flex-shrink: 0;

  border-radius: 999px;

  background: #F5F8F3;

  color: #607276;

  font-size: 9px;
  font-weight: 700;

  line-height: 1;
}


/* ==========================================================
   REMOVE SERVICENOW REPORT CARD SHELL
========================================================== */

.cm-ri-report {
  width: 100%;

  min-width: 0;
}


.cm-ri-report .panel,
.cm-ri-report .panel-default {
  margin: 0 !important;

  border: 0 !important;

  background:
    transparent !important;

  box-shadow:
    none !important;
}


.cm-ri-report .panel-heading,
.cm-ri-report .panel-title,
.cm-ri-report .report-title,
.cm-ri-report .widget-title {
  display:
    none !important;
}


.cm-ri-report .panel-body {
  margin:
    0 !important;

  padding:
    0 !important;

  background:
    transparent !important;
}


/* ==========================================================
   CHART AREA
========================================================== */

.cm-ri-chart-report {
  width: 100%;

  height: 225px;

  min-width: 0;

  min-height: 225px;

  max-height: 225px;

  flex: none;

  position: relative;

  margin: 0;

  padding: 0;

  overflow: visible;
}


.cm-ri-chart-report > * {
  width: 100%;
}


/* ==========================================================
   NESTED REPORT CONTAINER
========================================================== */

.cm-ri-chart-report .panel,
.cm-ri-chart-report .panel-body,
.cm-ri-chart-report .report-widget,
.cm-ri-chart-report .report-content,
.cm-ri-chart-report .report_content,
.cm-ri-chart-report .chart-container {
  width:
    100% !important;

  height:
    225px !important;

  min-height:
    225px !important;

  max-height:
    225px !important;

  margin:
    0 !important;

  padding:
    0 !important;

  border:
    0 !important;

  background:
    transparent !important;

  box-shadow:
    none !important;

  overflow:
    visible !important;
}


/* ==========================================================
   HIGHCHART BASE
========================================================== */

.cm-ri-chart-report
.highcharts-container,

.cm-ri-chart-report
.highcharts-root,

.cm-ri-chart-report
svg {
  overflow:
    visible !important;

  max-height:
    none !important;
}


/* ==========================================================
   DONUT POSITION
========================================================== */

.cm-ri-chart-card:not(.cm-ri-chart-wide)
.highcharts-series-group {
  transform-box:
    fill-box !important;

  transform-origin:
    center center !important;

  transform:
    translateY(-12px) !important;
}


/* ==========================================================
   DONUT LEGEND BELOW CHART
========================================================== */

.cm-ri-chart-card:not(.cm-ri-chart-wide)
.highcharts-legend {
  transform-box:
    fill-box !important;

  transform-origin:
    center center !important;

  transform:
    translateY(150px) !important;
}


.cm-ri-chart-card:not(.cm-ri-chart-wide)
.highcharts-legend-item text {
  font-size:
    11px !important;

  font-weight:
    600 !important;

  fill:
    #40585C !important;
}


.cm-ri-chart-card:not(.cm-ri-chart-wide)
.highcharts-legend-item rect {
  width:
    10px !important;

  height:
    10px !important;
}


/* ==========================================================
   BAR CHART
========================================================== */

.cm-ri-chart-wide
.cm-ri-chart-report {
  overflow:
    visible !important;
}


/* ==========================================================
   BAR LEGEND
========================================================== */

.cm-ri-chart-wide
.highcharts-legend {
  transform-box:
    fill-box !important;

  transform-origin:
    center center !important;

  transform:
    translateY(198px) !important;
}


.cm-ri-chart-wide
.highcharts-legend-item text {
  font-size:
    10px !important;

  font-weight:
    600 !important;

  fill:
    #40585C !important;
}


/* ==========================================================
   BAR X AXIS
========================================================== */

.cm-ri-chart-wide
.highcharts-xaxis-labels {
  transform:
    translateY(-8px) !important;
}


.cm-ri-chart-wide
.highcharts-xaxis-labels text {
  font-size:
    9px !important;

  font-weight:
    600 !important;

  fill:
    #506267 !important;
}


/* ==========================================================
   BAR Y AXIS
========================================================== */

.cm-ri-chart-wide
.highcharts-yaxis-labels text {
  font-size:
    10px !important;

  font-weight:
    600 !important;

  fill:
    #40585C !important;
}


.cm-ri-chart-wide
.highcharts-yaxis
.highcharts-axis-title {
  font-size:
    10px !important;

  font-weight:
    700 !important;

  fill:
    #254B4B !important;
}


/* ==========================================================
   BAR GRID
========================================================== */

.cm-ri-chart-wide
.highcharts-grid-line {
  stroke:
    #E5ECE8 !important;

  stroke-width:
    1px !important;
}


.cm-ri-chart-wide
.highcharts-axis-line {
  stroke:
    #BCCBC6 !important;
}


/* ==========================================================
   DATA LABELS
========================================================== */

.cm-ri-chart-report
.highcharts-data-label text {
  font-size:
    9px !important;

  font-weight:
    600 !important;

  fill:
    #40585C !important;
}


/* ==========================================================
   WARNING
========================================================== */

.cm-ri-warning {
  margin-top: 20px;

  padding:
    13px
    15px;

  display: flex;

  flex-direction: column;

  gap: 3px;

  border:
    1px solid
    #E7CFCB;

  border-radius: 13px;

  background: #FBF1EF;
}


.cm-ri-warning strong {
  color: #6F3F3A;

  font-size: 10px;
}


.cm-ri-warning span {
  color: #84615D;

  font-size: 9px;

  line-height: 1.5;
}


/* ==========================================================
   SMALL LAPTOP
========================================================== */

@media (max-width: 1100px) {

  .cm-ri-chart-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }


  .cm-ri-chart-wide {
    grid-column:
      span 2;
  }

}


/* ==========================================================
   TABLET
========================================================== */

@media (max-width: 950px) {

  .cm-ri-kpi-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

}


/* ==========================================================
   MOBILE
========================================================== */

@media (max-width: 700px) {

  .cm-ri {
    width: 100vw;

    margin-left:
      calc(50% - 50vw);

    padding:
      26px
      14px
      50px;
  }


  .cm-ri-header-row {
    flex-direction:
      column;

    align-items:
      flex-start;

    gap: 12px;
  }


  .cm-ri-header h2 {
    font-size: 25px;
  }


  .cm-ri-section-head {
    flex-direction:
      column;

    align-items:
      flex-start;

    gap: 4px;
  }


  .cm-ri-chart-grid {
    grid-template-columns:
      1fr;
  }


  .cm-ri-chart-wide {
    grid-column:
      auto;
  }

}


/* ==========================================================
   SMALL MOBILE
========================================================== */

@media (max-width: 430px) {

  .cm-ri-kpi-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );

    gap: 10px;
  }


  .cm-ri-kpi-card {
    min-height: 106px;

    padding:
      12px
      10px
      10px;
  }


  .cm-ri-kpi-label {
    min-height: 24px;

    padding-left: 11px;

    font-size: 10px;
  }


  .cm-ri-kpi-label::before {
    height: 19px;
  }


  .cm-ri-chart-card {
    height: 295px;

    padding:
      12px
      10px
      10px;
  }


  .cm-ri-chart-index {
    width: 27px;
    height: 27px;

    font-size: 9px;
  }


  .cm-ri-chart-heading h4 {
    font-size: 12px;
  }


  .cm-ri-chart-type {
    min-height: 22px;

    padding:
      4px
      7px;

    font-size: 8px;
  }


  .cm-ri-chart-card:not(.cm-ri-chart-wide)
  .highcharts-legend-item text {
    font-size:
      9px !important;
  }

}

/* ==========================================================
   LAPTOP / DESKTOP READABILITY POLISH
   Text only — chart geometry, cards and responsive layout stay unchanged.
========================================================== */

@media (min-width: 1101px) {

  .cm-ri-eyebrow {
    font-size: 11px;
  }

  .cm-ri-header p {
    font-size: 13px;
    line-height: 1.6;
  }

  .cm-ri-live {
    font-size: 10px;
  }

  .cm-ri-section-kicker {
    font-size: 9px;
  }

  .cm-ri-section-head h3 {
    font-size: 18px;
  }

  .cm-ri-section-head > p {
    font-size: 10px;
  }

  .cm-ri-chart-index {
    font-size: 11px;
  }

  .cm-ri-chart-heading h4 {
    font-size: 14px;
  }

  .cm-ri-chart-type {
    font-size: 10px;
  }

  .cm-ri-chart-card:not(.cm-ri-chart-wide)
  .highcharts-legend-item text {
    font-size: 12px !important;
  }

  .cm-ri-chart-wide
  .highcharts-legend-item text {
    font-size: 11px !important;
  }

  .cm-ri-chart-wide
  .highcharts-xaxis-labels text {
    font-size: 10px !important;
  }

  .cm-ri-chart-wide
  .highcharts-yaxis-labels text {
    font-size: 11px !important;
  }

  .cm-ri-chart-wide
  .highcharts-yaxis
  .highcharts-axis-title {
    font-size: 11px !important;
  }

  .cm-ri-chart-report
  .highcharts-data-label text {
    font-size: 10px !important;
  }

  .cm-ri-warning strong {
    font-size: 11px;
  }

  .cm-ri-warning span {
    font-size: 10px;
  }
}
/* ==========================================================
   FINAL ANALYTICS LEGEND POSITION POLISH
========================================================== */


/* ----------------------------------------------------------
   DONUT LEGENDS
   Keep information neatly below each pie
---------------------------------------------------------- */

.cm-ri-chart-card:not(.cm-ri-chart-wide)
.highcharts-legend {
  transform-box: fill-box !important;
  transform-origin: center center !important;

  transform:
    translateY(143px) !important;
}


/* Match Quality has 3 legend rows */

.cm-ri-chart-card:nth-child(3)
.highcharts-legend {
  transform:
    translateY(137px) !important;
}


/* ----------------------------------------------------------
   BAR CHART LEGEND
   Move Found / Lost slightly upward
---------------------------------------------------------- */

.cm-ri-chart-wide
.highcharts-legend {
  transform-box: fill-box !important;
  transform-origin: center center !important;

  transform:
    translateY(188px) !important;
}

sp_widget.script:
(function() {

    /* ======================================================
       STAFF ACCESS
    ====================================================== */

    data.authorized = false;

    data.kpis = [];
    data.charts = [];
    data.missingReports = [];


    var access =
        new CampusMatchAccess();


    data.authorized =
        access.isStaff();


    /*
     * Do not expose staff analytics to
     * unauthorised portal users.
     */
    if (!data.authorized) {
        return;
    }



    /* ======================================================
       REPORT CONFIGURATION

       IMPORTANT:
       reportTitle must EXACTLY match sys_report.title.
    ====================================================== */

    var KPI_CONFIG = [

        {
            key: 'total',
            label: 'Total Reports',
            reportTitle:
                'CampusMatch - Total Reports'
        },

        {
            key: 'active_lost',
            label: 'Active Lost',
            reportTitle:
                'CampusMatch - Active Lost Reports'
        },

        {
            key: 'claims_review',
            label: 'Claims Review',
            reportTitle:
                'CampusMatch - Claims Needing Review'
        },

        {
            key: 'strong_matches',
            label: 'Strong Matches',
            reportTitle:
                'CampusMatch - Strong Matches'
        },

        {
            key: 'ready_collection',
            label: 'Ready for Collection',
            reportTitle:
                'CampusMatch - Ready for Collection'
        },

        {
            key: 'recovered',
            label: 'Items Recovered',
            reportTitle:
                'CampusMatch - Items Recovered'
        },

        {
            key: 'pending_matches',
            label: 'Pending Matches',
            reportTitle:
                'CampusMatch - Pending PI Matches'
        },

        {
            key: 'average_confidence',
            label: 'Avg. Match Confidence',
            reportTitle:
                'CampusMatch - Average Match Confidence'
        }

    ];


    var CHART_CONFIG = [

        {
            key: 'lost_found',
            index: '01',
            label: 'Lost vs Found',
            typeLabel: 'Reports',
            reportTitle:
                'CampusMatch - Lost vs Found'
        },

        {
            key: 'report_status',
            index: '02',
            label: 'Report Status',
            typeLabel: 'Status',
            reportTitle:
                'CampusMatch - Report Status'
        },

        {
            key: 'match_quality',
            index: '03',
            label: 'Match Quality',
            typeLabel: 'Matching',
            reportTitle:
                'CampusMatch - Match Quality'
        },

        {
            key: 'claim_verification',
            index: '04',
            label: 'Claim Verification',
            typeLabel: 'Claims',
            reportTitle:
                'CampusMatch - Claim Verification'
        },

        {
            key: 'security_desk',
            index: '05',
            label: 'Security Desk Intake',
            typeLabel: 'Custody',
            reportTitle:
                'CampusMatch - Security Desk Intake'
        },

        {
            key: 'collection_status',
            index: '06',
            label: 'Collection Status',
            typeLabel: 'Handover',
            reportTitle:
                'CampusMatch - Collection Status'
        },

        {
            key: 'category',
            index: '07',
            label: 'Reports by Category',
            typeLabel: 'Categories',
            reportTitle:
                'CampusMatch - Reports by Category',
            wide: true
        }

    ];



    /* ======================================================
       BUILD LIST OF REPORT TITLES
    ====================================================== */

    var requestedTitles = [];


    KPI_CONFIG.forEach(
        function(config) {

            requestedTitles.push(
                config.reportTitle
            );

        }
    );


    CHART_CONFIG.forEach(
        function(config) {

            requestedTitles.push(
                config.reportTitle
            );

        }
    );



    /* ======================================================
       LOAD REPORT SYS_IDS IN ONE QUERY
    ====================================================== */

    var reportIds = {};


    var reportGR =
        new GlideRecord(
            'sys_report'
        );


    reportGR.addQuery(
        'title',
        'IN',
        requestedTitles.join(',')
    );


    reportGR.query();


    while (
        reportGR.next()
    ) {

        reportIds[
            reportGR.getValue('title')
        ] =
            reportGR.getUniqueValue();

    }



    /* ======================================================
       CREATE NESTED REPORT WIDGET
    ====================================================== */

    function buildReportWidget(
        reportTitle
    ) {

        var reportId =
            reportIds[
                reportTitle
            ];


        if (!reportId) {

            data.missingReports.push(
                reportTitle
            );

            return null;

        }


        /*
         * The OOB Service Portal Report widget
         * receives the sys_report sys_id.
         *
         * show_title = false because CampusMatch
         * supplies its own shorter labels.
         */

        var reportOptions = {

            report_id:
                reportId,

            show_title:
                false,

            widget_parameters:
                JSON.stringify({

                    report_id: {

                        value:
                            reportId,

                        displayValue:
                            reportTitle

                    },

                    show_title: {

                        value:
                            'false',

                        displayValue:
                            'false'

                    }

                })

        };


        return $sp.getWidget(
            'report',
            reportOptions
        );

    }



    /* ======================================================
       BUILD KPI MODELS
    ====================================================== */

    KPI_CONFIG.forEach(
        function(config) {

            var reportWidget =
                buildReportWidget(
                    config.reportTitle
                );


            if (!reportWidget) {
                return;
            }


            data.kpis.push({

                key:
                    config.key,

                label:
                    config.label,

                widget:
                    reportWidget

            });

        }
    );



    /* ======================================================
       BUILD CHART MODELS
    ====================================================== */

    CHART_CONFIG.forEach(
        function(config) {

            var reportWidget =
                buildReportWidget(
                    config.reportTitle
                );


            if (!reportWidget) {
                return;
            }


            data.charts.push({

                key:
                    config.key,

                index:
                    config.index,

                label:
                    config.label,

                typeLabel:
                    config.typeLabel,

                wide:
                    config.wide === true,

                widget:
                    reportWidget

            });

        }
    );


})();
